@@ -6669,4 +6669,4 @@
-      // (x & y) ^ (~x & z)
-      __ andr(t0, x, y);
-      __ andn(dst, z, x);
-      __ xorr(dst, dst, t0);
+      // (x & y) ^ (~x & z) = z ^ (x & (y ^ z))
+      __ xorr(dst, y, z);
+      __ andr(dst, x, dst);
