@@ -6891,0 +6877,9 @@
+
+      // Software register renaming for next round:
+      //   a' = e, b' = a, c' = b, d' = c, e' = d
+      Register old_e = e;
+      e = d;
+      d = c;
+      c = b;
+      b = a;
+      a = old_e;
